(function () {
  'use strict';

  var endpoint = 'https://abacus.jasoncameron.dev/hit/chenzihao-me/';
  var siteNode = document.getElementById('busuanzi_value_site_pv') ||
    document.getElementById('busuanzi_value_site_uv');
  var pageNode = document.getElementById('busuanzi_value_page_pv');

  function counterKey(value) {
    return encodeURIComponent(value).replace(/%/g, '_');
  }

  function show(node, value) {
    if (node) node.textContent = value;
  }

  function hit(counter, node) {
    if (!node) return;
    if (!window.fetch) {
      show(node, '—');
      return;
    }
    show(node, '…');
    fetch(endpoint + counter, { cache: 'no-store', mode: 'cors' })
      .then(function (response) {
        if (!response.ok) throw new Error('counter request failed');
        return response.json();
      })
      .then(function (data) {
        if (typeof data.value !== 'number') throw new Error('invalid counter response');
        show(node, String(data.value));
      })
      .catch(function () {
        show(node, '—');
      });
  }

  hit('site', siteNode);
  hit('page-' + counterKey(window.location.pathname), pageNode);
})();
